<div class="d-flex justify-content-between align-items-center"><h1 class="page-title">Tài khoản của tôi</h1><div class="d-flex gap-2"><a href="/orders" class="btn btn-outline-primary">Lịch sử mua hàng</a><form action="/logout" method="post"><?= App\Core\Csrf::field() ?><button id="customer-logout" type="submit" class="btn btn-light">Đăng xuất</button></form></div></div><div class="row"><div class="col-lg-6"><section class="panel"><h2>Thông tin cá nhân</h2><form action="/account" method="post"><?= App\Core\Csrf::field() ?><label class="form-label" for="profile-name">Họ và tên</label><input class="form-control" id="profile-name" name="name" value="<?= e($user['name']) ?>" required><label class="form-label" for="profile-phone">Điện thoại</label><input class="form-control" id="profile-phone" name="phone" value="<?= e($user['phone']) ?>"><p class="muted mt-3"><?= e($user['email']) ?></p><button id="profile-save" class="btn btn-primary" type="submit">Lưu thông tin</button></form></section><section class="panel"><h2>Đổi mật khẩu</h2><form action="/account/password" method="post"><?= App\Core\Csrf::field() ?><?php foreach(['current_password'=>'Mật khẩu hiện tại','password'=>'Mật khẩu mới (tối thiểu 10 ký tự)','password_confirmation'=>'Xác nhận mật khẩu mới'] as $name=>$label):?><label class="form-label" for="profile-<?= $name ?>"><?= $label ?></label><input class="form-control" type="password" name="<?= $name ?>" id="profile-<?= $name ?>" required autocomplete="<?= $name==='current_password'?'current-password':'new-password' ?>"><?php endforeach?><button id="password-save" type="submit" class="btn btn-primary mt-3">Đổi mật khẩu</button></form></section></div><div class="col-lg-6"><section class="panel"><h2>Địa chỉ nhận hàng</h2><?php foreach($addresses as $address):?><div class="border-bottom py-3"><b><?= e($address['recipient']) ?></b> <?= $address['is_default']?'<span class="badge-soft">Mặc định</span>':'' ?><p class="muted mt-2"><?= e($address['phone']) ?><br><?= e($address['address_line']) ?></p><form action="/account/addresses/<?= $address['id'] ?>" method="post" class="d-flex gap-2"><?= App\Core\Csrf::field() ?><button class="btn btn-light btn-sm" name="action" value="default" type="submit">Đặt mặc định</button><button class="btn btn-light btn-sm" name="action" value="delete" type="submit">Xóa</button></form></div><?php endforeach?></section><section class="panel"><h2>Thêm địa chỉ</h2><form action="/account/addresses" method="post"><?= App\Core\Csrf::field() ?><?php foreach(['recipient'=>'Người nhận','phone'=>'Điện thoại','address_line'=>'Địa chỉ đầy đủ'] as $name=>$label):?><label class="form-label" for="address-<?= $name ?>"><?= $label ?></label><input class="form-control" name="<?= $name ?>" id="address-<?= $name ?>" required><?php endforeach?><label class="d-block my-3"><input type="checkbox" name="is_default" value="1"> Đặt làm địa chỉ mặc định</label><button id="address-save" class="btn btn-primary" type="submit">Thêm địa chỉ</button></form></section></div></div>
